package tv.iptvibe.mobile;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.widget.*;import android.view.*;import org.json.*;import java.net.*;import java.io.*;import java.util.*;import java.text.*;import java.util.concurrent.*;
/** Touch adapter for the shared football gateway. Broadcast rights are never guessed. */
public class FootballActivity extends Activity {
 private final ExecutorService net=Executors.newFixedThreadPool(3);private final Handler ui=new Handler(Looper.getMainLooper());private LinearLayout root,list;private TextView status;private JSONArray leagues=new JSONArray();private String league="bra.1",mode="games";private Calendar day=Calendar.getInstance();private volatile int serial;private final int GREEN=0xff27e4a8,TEXT=0xffedf3f0,BG=0xff090d10;
 private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}private TextView text(String s,int n){TextView v=new TextView(this);v.setText(s);v.setTextSize(n);v.setTextColor(TEXT);v.setPadding(dp(8),dp(8),dp(8),dp(8));return v;}private Button button(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextColor(GREEN);b.setOnClickListener(v->r.run());return b;}private String date(){return new SimpleDateFormat("yyyyMMdd",Locale.ROOT).format(day.getTime());}
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);layout();load();}
 private void layout(){root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(12),dp(8),dp(12),dp(8));root.setBackgroundColor(BG);setContentView(root);root.addView(text("Futebol · IPTVibe",28));root.addView(text("O jogo começa aqui.",18));HorizontalScrollView tabs=new HorizontalScrollView(this);LinearLayout nav=new LinearLayout(this);for(String[] pair:new String[][]{{"games","▶ Jogos"},{"calendar","▦ Calendário"},{"table","≡ Classificação"},{"reminders","◷ Lembretes"}})nav.addView(button(pair[1],()->{mode=pair[0];load();}));nav.addView(button("Voltar",this::finish));tabs.addView(nav);root.addView(tabs);Spinner select=new Spinner(this);List<String> names=new ArrayList<>();int chosen=0;for(int i=0;i<leagues.length();i++){JSONObject l=leagues.optJSONObject(i);names.add(l.optString("name"));if(l.optString("id").equals(league))chosen=i;}if(names.isEmpty())names.add("Brasileirão Série A");select.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,names));select.setSelection(chosen);root.addView(select);select.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,View v,int n,long id){if(n<leagues.length()){String next=leagues.optJSONObject(n).optString("id");if(!league.equals(next)){league=next;load();}}}});LinearLayout dates=new LinearLayout(this);dates.addView(button("‹",()->{day.add(Calendar.DATE,-1);load();}),new LinearLayout.LayoutParams(0,dp(52),1));dates.addView(button(new SimpleDateFormat("dd/MM/yyyy",Locale.ROOT).format(day.getTime()),()->new DatePickerDialog(this,(picker,y,m,d)->{day.set(y,m,d);load();},day.get(Calendar.YEAR),day.get(Calendar.MONTH),day.get(Calendar.DAY_OF_MONTH)).show()),new LinearLayout.LayoutParams(0,dp(52),3));dates.addView(button("›",()->{day.add(Calendar.DATE,1);load();}),new LinearLayout.LayoutParams(0,dp(52),1));root.addView(dates);status=text("Consultando programação…",14);status.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);root.addView(status);ScrollView scroll=new ScrollView(this);list=new LinearLayout(this);list.setOrientation(1);scroll.addView(list);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));root.addView(button("Atualizar",this::load));}
 private JSONObject get(String params)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL("https://iptvibe.pages.dev/api/football?"+params).openConnection();c.setConnectTimeout(12000);c.setReadTimeout(15000);try{if(c.getResponseCode()!=200)throw new IOException();try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>4000000)throw new IOException();out.write(b,0,n);}return new JSONObject(out.toString("UTF-8"));}}finally{c.disconnect();}}
 private android.content.SharedPreferences prefs(){return getSharedPreferences("football-reminders",0);}private JSONArray reminders(){try{return new JSONArray(prefs().getString("games","[]"));}catch(Exception e){return new JSONArray();}}
 private void load(){int ticket=++serial;layout();if(mode.equals("reminders")){games(reminders());status.setText("Lembretes deste aparelho. O Android pode atrasar avisos para economizar bateria.");return;}final String selected=league,action=mode.equals("table")?"table":"games",selectedMode=mode;net.execute(()->{try{JSONObject d=get("league="+selected+"&action="+action+"&date="+date());ui.post(()->{if(ticket!=serial||isDestroyed())return;if(leagues.length()==0){leagues=d.optJSONArray("leagues");if(leagues==null)leagues=new JSONArray();layout();}status.setText("Atualizado em "+d.optString("updatedAt").replace('T',' ').replace(".000Z"," UTC")+(d.optBoolean("stale")?" · dados salvos":""));if(selectedMode.equals("table"))table(d.optJSONArray("groups"));else{JSONArray all=d.optJSONArray("games"),rows=new JSONArray();if(all!=null)for(int i=0;i<all.length();i++){JSONObject g=all.optJSONObject(i);if(selectedMode.equals("calendar")||(!g.optString("state").equals("post")&&g.optJSONArray("channels").length()>0))rows.put(g);}games(rows);}});}catch(Exception e){ui.post(()->{if(ticket==serial)status.setText("Não foi possível atualizar. Toque em Atualizar para tentar novamente.");});}});}
 private void image(LinearLayout parent,String uri,int size){ImageView v=new ImageView(this);v.setScaleType(ImageView.ScaleType.FIT_CENTER);v.setImageResource(tv.iptvibe.mobile.R.drawable.iptvibe_icon);parent.addView(v,new LinearLayout.LayoutParams(dp(size),dp(size)));if(!uri.startsWith("https://"))return;net.execute(()->{try{HttpURLConnection c=(HttpURLConnection)new URL(uri).openConnection();c.setConnectTimeout(5000);c.setReadTimeout(5000);try(InputStream in=c.getInputStream()){Bitmap b=BitmapFactory.decodeStream(in);if(b!=null)ui.post(()->v.setImageBitmap(b));}finally{c.disconnect();}}catch(Exception ignored){}});}
 private void games(JSONArray rows){list.removeAllViews();if(rows==null||rows.length()==0){list.addView(text(mode.equals("games")?"Nenhuma transmissão identificada nesta seleção. Confira o Calendário. Não presumimos direitos de transmissão.":"Nenhuma partida disponível nesta seleção. Escolha outra data ou competição.",16));return;}for(int i=0;i<rows.length();i++){JSONObject g=rows.optJSONObject(i);LinearLayout card=new LinearLayout(this);card.setOrientation(1);card.setPadding(dp(12),dp(14),dp(12),dp(14));card.setBackgroundColor(0xff123329);LinearLayout heading=new LinearLayout(this);image(heading,g.optString("leagueLogo"),32);heading.addView(text(g.optString("leagueName"),15));card.addView(heading);LinearLayout teams=new LinearLayout(this);teams.setGravity(Gravity.CENTER);image(teams,g.optString("homeLogo"),48);teams.addView(text(g.optString("score"),25));image(teams,g.optString("awayLogo"),48);card.addView(teams);card.addView(text(g.optString("home")+" × "+g.optString("away"),20));card.addView(text(g.optString("date").replace('T',' ').replace("Z"," UTC")+" · "+g.optString("status"),14));card.setFocusable(true);card.setContentDescription(g.optString("home")+" contra "+g.optString("away"));card.setOnClickListener(v->details(g));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(16);list.addView(card,p);}}
 private void table(JSONArray groups){list.removeAllViews();if(groups==null||groups.length()==0){list.addView(text("A classificação ainda não foi publicada para esta competição.",16));return;}for(int i=0;i<groups.length();i++){JSONObject group=groups.optJSONObject(i);list.addView(text(group.optString("name"),22));list.addView(text("Posição · Clube · Pontos · Jogos · Vitórias · Empates · Derrotas · Saldo",13));JSONArray rows=group.optJSONArray("rows");for(int j=0;j<rows.length();j++){JSONObject r=rows.optJSONObject(j);LinearLayout row=new LinearLayout(this);image(row,r.optString("logo"),28);row.addView(text((r.optInt("rank")>0?r.optString("rank"):"—")+" · "+r.optString("name")+"\n"+r.optString("points")+" Pts · "+r.optString("played")+" J · "+r.optString("won")+" V · "+r.optString("drawn")+" E · "+r.optString("lost")+" D · "+r.optString("difference")+" SG",15));list.addView(row);}}}
 private void details(JSONObject game){LinearLayout form=new LinearLayout(this);form.setOrientation(1);JSONArray channels=game.optJSONArray("channels");form.addView(text(channels.length()>0?"Transmissão identificada: "+channels.toString().replaceAll("[\\[\\]\"]",""):"Nenhum canal de transmissão confirmado para esta partida.",16));AlertDialog dialog=new AlertDialog.Builder(this).setTitle(game.optString("home")+" × "+game.optString("away")).setView(form).setNegativeButton("Voltar",null).create();for(int i=0;i<channels.length();i++){String channel=channels.optString(i);form.addView(button("Assistir em "+channel,()->{dialog.dismiss();try{startActivity(new Intent(this,PlayerActivity.class).putExtra("selection",new JSONObject().put("kind","live").put("title",channel).toString()).putExtra("source",0));}catch(Exception ignored){}}));}form.addView(button("◷ Adicionar ou remover lembrete",()->remind(game)));TextView data=text("Consultando escalações e estatísticas…",15);form.addView(data);dialog.show();net.execute(()->{try{JSONObject d=get("league="+game.optString("league")+"&action=detail&event="+game.optString("id"));StringBuilder s=new StringBuilder("Escalações\n");JSONArray rosters=d.optJSONArray("rosters");if(rosters==null||rosters.length()==0)s.append("Ainda não disponíveis.\n");else for(int i=0;i<rosters.length();i++){JSONObject team=rosters.optJSONObject(i);s.append(team.optJSONObject("team").optString("displayName")).append("\n");JSONArray players=team.optJSONArray("roster");if(players!=null)for(int j=0;j<players.length();j++){JSONObject player=players.optJSONObject(j).optJSONObject("athlete");if(player!=null)s.append(player.optString("displayName")).append(" · ");}s.append("\n");}s.append("\nEstatísticas\n");JSONArray stats=d.optJSONArray("statistics");if(stats==null||stats.length()==0)s.append("Ainda não disponíveis.\n");else for(int i=0;i<stats.length();i++){JSONObject t=stats.optJSONObject(i);s.append(t.optJSONObject("team").optString("displayName")).append("\n");JSONArray values=t.optJSONArray("statistics");if(values!=null)for(int j=0;j<values.length();j++){JSONObject v=values.optJSONObject(j);s.append(v.optString("label",v.optString("name"))).append(": ").append(v.optString("displayValue",v.optString("value"))).append("\n");}}ui.post(()->{if(dialog.isShowing())data.setText(s.toString());});}catch(Exception e){ui.post(()->data.setText("Não foi possível consultar os detalhes agora."));}});}
 private void remind(JSONObject game){try{JSONArray old=reminders(),next=new JSONArray();boolean remove=false;for(int i=0;i<old.length();i++){JSONObject r=old.optJSONObject(i);if(r.optString("id").equals(game.optString("id")))remove=true;else next.put(r);}if(!remove)next.put(game);prefs().edit().putString("games",next.toString()).apply();Intent intent=new Intent(this,FootballReminderReceiver.class).putExtra("title",game.optString("home")+" × "+game.optString("away"));PendingIntent pending=PendingIntent.getBroadcast(this,game.optString("id").hashCode(),intent,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);AlarmManager alarm=(AlarmManager)getSystemService(ALARM_SERVICE);if(remove)alarm.cancel(pending);else{java.time.Instant kickoff=java.time.Instant.parse(game.optString("date"));long at=Math.max(System.currentTimeMillis()+10000,kickoff.toEpochMilli()-900000);if(kickoff.toEpochMilli()<=System.currentTimeMillis()){Toast.makeText(this,"Esta partida já começou ou foi encerrada.",Toast.LENGTH_LONG).show();return;}if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},14);alarm.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,at,pending);}Toast.makeText(this,remove?"Lembrete removido.":"Lembrete salvo para antes da partida.",Toast.LENGTH_LONG).show();}catch(Exception e){Toast.makeText(this,"Não foi possível salvar o lembrete.",Toast.LENGTH_LONG).show();}}
 @Override public void onDestroy(){serial++;net.shutdownNow();super.onDestroy();}
}
